import React, {useEffect, useState} from 'react';
import api from '../api';

export default function Dashboard(){
  const [me, setMe] = useState(null);

  useEffect(()=>{
    api.get('/user_info/')
      .then(r => {
        setMe(r.data);
      })
      .catch(err => console.error("خطا در گرفتن اطلاعات کاربر:", err));
  },[]);

  return (
    <div style={{padding:20, direction:'rtl'}}>
      <h2>داشبورد</h2>
      {me ? (
        <div>
          <p>خوش آمدی {me.fullname}</p>
          <p>سهم ماهیانه: {me.monthly_charge}</p>
          <a href='/deposit'>ثبت واریز</a> | <a href='/loan'>درخواست وام</a>
        </div>
      ) : (
        <p>در حال بارگذاری...</p>
      )}
    </div>
  )
}
